function retryWithError(fn, attempts, onRetry) {
  let lastErr;
  for (let i = 1; i <= attempts; i++) {
    try {
      return fn(i);
    } catch (err) {
      lastErr = err;
      if (i < attempts) onRetry(err, i);
    }
  }
  throw lastErr;
}

