class CircuitOpenError extends Error {
  constructor() {
    super("circuit open");
    this.name = "CircuitOpenError";
  }
}

function createBreaker(threshold, cooldownMs) {
  let failures = 0;
  let openedAt = 0;
  return function run(fn) {
    if (failures >= threshold) {
      if (Date.now() - openedAt < cooldownMs) throw new CircuitOpenError();
      failures = 0; // half-open: allow a trial call
    }
    try {
      return fn();
    } catch (err) {
      failures++;
      if (failures >= threshold) openedAt = Date.now();
      throw err;
    }
  };
}

